content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
  overflow-x: hidden;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  min-height: 100vh;
  padding: 20px;
  max-width: 800px;
  margin: 0 auto;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 16px;
  text-align: center;
  color: #38bdf8;
  letter-spacing: 0.05em;
}

.canvas-container {
  width: 100%;
  max-width: 450px;
  height: 450px;
  background: #1e293b;
  border-radius: 16px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  position: relative;
  margin-bottom: 20px;
  border: 1px solid #334155;
  touch-action: none;
}

.canvas-container canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

.controls-info {
  font-size: 0.95rem;
  color: #94a3b8;
  text-align: center;
  margin-bottom: 20px;
  background: #1e293b;
  padding: 12px 20px;
  border-radius: 8px;
  border: 1px solid #334155;
  max-width: 450px;
  width: 100%;
}

.btn {
  background-color: #0284c7;
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.2);
}

.btn:hover {
  background-color: #0369a1;
}

.btn:active {
  transform: scale(0.98);
}

.btn:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

@media (max-width: 480px) {
  .app-container {
    padding: 12px;
  }

  .title {
    font-size: 1.5rem;
  }

  .canvas-container {
    height: min(60vh, 350px);
  }
}

import { useEffect, useRef, useState, useCallback } from 'react'
import * as THREE from 'three'
import './index.css'

export default function App() {
  const mountRef = useRef<HTMLDivElement>(null)
  const [cubeColor, setCubeColor] = useState<number>(0x38bdf8)

  const sceneRef = useRef<THREE.Scene | null>(null)
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null)
  const cubeRef = useRef<THREE.Mesh | null>(null)
  const isDraggingRef = useRef<boolean>(false)
  const previousMousePositionRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 })

  const colors = [0x38bdf8, 0xef4444, 0x10b981, 0xf59e0b, 0x8b5cf6, 0xec4899]

  const changeColor = useCallback(() => {
    const randomColor = colors[Math.floor(Math.random() * colors.length)]
    setCubeColor(randomColor)
    if (cubeRef.current) {
      const material = cubeRef.current.material as THREE.MeshStandardMaterial
      material.color.setHex(randomColor)
    }
  }, [])

  useEffect(() => {
    const currentMount = mountRef.current
    if (!currentMount) return

    const width = currentMount.clientWidth
    const height = currentMount.clientHeight

    // Scene
    const scene = new THREE.Scene()
    sceneRef.current = scene

    // Camera
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 1000)
    camera.position.z = 5

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true })
    renderer.setSize(width, height)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
    currentMount.appendChild(renderer.domElement)
    rendererRef.current = renderer

    // Lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7)
    scene.add(ambientLight)

    const pointLight = new THREE.PointLight(0xffffff, 1)
    pointLight.position.set(5, 5, 5)
    scene.add(pointLight)

    // Cube
    const geometry = new THREE.BoxGeometry(2, 2, 2)
    const material = new THREE.MeshStandardMaterial({
      color: cubeColor,
      roughness: 0.3,
      metalness: 0.2,
    })
    const cube = new THREE.Mesh(geometry, material)
    scene.add(cube)
    cubeRef.current = cube

    // Animation loop
    let animationFrameId: number
    const animate = () => {
      animationFrameId = requestAnimationFrame(animate)

      if (!isDraggingRef.current && cubeRef.current) {
        cubeRef.current.rotation.x += 0.005
        cubeRef.current.rotation.y += 0.007
      }

      renderer.render(scene, camera)
    }
    animate()

    // Pointer events for rotation with pointer capture
    const handlePointerDown = (e: PointerEvent) => {
      isDraggingRef.current = true
      previousMousePositionRef.current = { x: e.clientX, y: e.clientY }
      try {
        ;(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)
      } catch {
        // ignore
      }
    }

    const handlePointerMove = (e: PointerEvent) => {
      if (!isDraggingRef.current || !cubeRef.current) return

      const deltaX = e.clientX - previousMousePositionRef.current.x
      const deltaY = e.clientY - previousMousePositionRef.current.y

      cubeRef.current.rotation.y += deltaX * 0.01
      cubeRef.current.rotation.x += deltaY * 0.01

      previousMousePositionRef.current = { x: e.clientX, y: e.clientY }
    }

    const handlePointerUp = (e: PointerEvent) => {
      if (isDraggingRef.current) {
        isDraggingRef.current = false
        try {
          ;(e.currentTarget as HTMLElement).releasePointerCapture(e.pointerId)
        } catch {
          // ignore
        }
      }
    }

    currentMount.addEventListener('pointerdown', handlePointerDown)
    currentMount.addEventListener('pointermove', handlePointerMove)
    currentMount.addEventListener('pointerup', handlePointerUp)
    currentMount.addEventListener('pointercancel', handlePointerUp)

    // Resize handler
    const handleResize = () => {
      if (!currentMount) return
      const newWidth = currentMount.clientWidth
      const newHeight = currentMount.clientHeight
      camera.aspect = newWidth / newHeight
      camera.updateProjectionMatrix()
      renderer.setSize(newWidth, newHeight)
    }

    window.addEventListener('resize', handleResize)

    return () => {
      window.removeEventListener('resize', handleResize)
      if (currentMount) {
        currentMount.removeEventListener('pointerdown', handlePointerDown)
        currentMount.removeEventListener('pointermove', handlePointerMove)
        currentMount.removeEventListener('pointerup', handlePointerUp)
        currentMount.removeEventListener('pointercancel', handlePointerUp)
      }
      cancelAnimationFrame(animationFrameId)
      if (renderer.domElement && currentMount.contains(renderer.domElement)) {
        currentMount.removeChild(renderer.domElement)
      }
      renderer.dispose()
      geometry.dispose()
      material.dispose()
    }
  }, [])

  const colorHexStr = `#${cubeColor.toString(16).padStart(6, '0')}`

  return (
    <div className="app-container">
      <h1 className="title">3D 立方体ビューアー</h1>
      <div className="canvas-container" ref={mountRef} />
      <div className="controls-info">
        マウスまたは指でドラッグして立方体を自由に回転させることができます。
        <div style={{ marginTop: '8px', fontSize: '0.85rem', color: '#38bdf8' }}>
          現在のカラー: {colorHexStr}
        </div>
      </div>
      <button className="btn" onClick={changeColor}>
        色を変える
      </button>
    </div>
  )
}
